function initFolderBrowser() {
  const api = Websandbox.connection.remote;
  const el = id => document.getElementById(id);
  const selected = new Set();
  let folder = '', offset = 0, next = null, busy = false;
  async function browse(path = '', start = 0) {
    if (busy) return;
    busy = true; el('status').textContent = 'Loading folder…';
    try {
      const page = await api.listDirectory({path, offset:start, limit:100});
      folder = path; offset = start; next = page.nextOffset;
      el('location').textContent = path || 'Connected folder';
      el('files').replaceChildren();
      for (const entry of page.entries) {
        const button = document.createElement('button');
        button.textContent = (entry.directory ? '▸ ' : '') + entry.name;
        button.type = 'button';
        if (entry.directory) button.onclick = () => browse(entry.path);
        else {
          button.setAttribute('aria-pressed',String(selected.has(entry.path)));
          button.onclick = () => {
            if (selected.has(entry.path)) selected.delete(entry.path);
            else if (selected.size < 16) selected.add(entry.path);
            button.setAttribute('aria-pressed',String(selected.has(entry.path)));
            el('start').disabled = !selected.size;
            el('status').textContent = selected.size + ' selected';
          };
        }
        el('files').append(button);
      }
      el('back').disabled = !path;
      el('previous').disabled = !start;
      el('next').disabled = next == null;
      el('status').textContent = page.entries.length ? selected.size + ' selected' : 'Empty folder';
    } catch (error) { el('status').textContent = error.message || 'Could not open folder'; }
    finally { busy = false; }
  }
  el('back').onclick = () => browse(folder.split('/').slice(0,-1).join('/'));
  el('previous').onclick = () => browse(folder,Math.max(0,offset-100));
  el('next').onclick = () => next == null ? undefined : browse(folder,next);
  el('start').onclick = async () => {
    if (!selected.size || busy) return;
    el('start').disabled = true;
    try {
      await api.sendPrompt({text:JSON.stringify({files:[...selected]}),sourceFiles:[...selected]});
      el('status').textContent = 'Submitted · continue in chat';
    } catch (error) { el('status').textContent = error.message || 'Not sent'; el('start').disabled = false; }
  };
  browse();
}
